mod solution;

fn main() {
    let cases = [
    (r#"[4, 2, 4, 3, 2, 4]"#, r#"4"#),
    (r#"[3, 2, 3, 2]"#, r#"2"#),
    (r#"
[3, 2, 3, 2]
"#, r#"2"#),
    (r#"  
[4, 2, 4, 3, 2, 4]
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS frequency-counting");
}
